//! 🛬️ Original receiving authority admits every concrete composed-carrier allocation.
use super::archive_schema::*;
use semio_framework_value::{NativeDecodeControl,RetainedCloneGrant,retained_clone::RetainedCloneProgress,ValueError,ValueRefusalKind};
use crate::os_store::NativeSnapshotBodyWallet;
struct Reader<'a>{bytes:&'a[u8],position:usize}
impl<'a> Reader<'a>{
 fn varint(&mut self,control:&mut NativeDecodeControl<'_>)->Result<u64,ValueError>{let mut value=0u64;for index in 0..10{let byte=*self.bytes.get(self.position).ok_or_else(||ValueError::literal(ValueRefusalKind::InvalidValue,"truncated archive varint"))?;self.position+=1;control.step()?;if index==9&&byte>1{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"archive varint exceeds u64"))}value|=u64::from(byte&127)<<(index*7);if byte&128==0{return Ok(value)}}Err(ValueError::literal(ValueRefusalKind::InvalidValue,"archive varint exceeds ten bytes"))}
 fn field(&mut self,control:&mut NativeDecodeControl<'_>)->Result<&'a[u8],ValueError>{let length=usize::try_from(self.varint(control)?).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"archive field extent exceeds address space"))?;let end=self.position.checked_add(length).filter(|end|*end<=self.bytes.len()).ok_or_else(||ValueError::literal(ValueRefusalKind::InvalidValue,"truncated archive field"))?;let bytes=&self.bytes[self.position..end];self.position=end;control.advance(length)?;Ok(bytes)}
 fn text(&mut self,output:&mut String,control:&mut NativeDecodeControl<'_>,body:&mut NativeSnapshotBodyWallet,depth:usize)->Result<(),ValueError>{let bytes=self.field(control)?;let text=control.borrow_text(bytes)?;control.scoped_stage(|control|{control.begin_stage(text.len())?;body.copy_text_into(control,text,output,depth)})}
 fn bytes(&mut self,output:&mut Vec<u8>,control:&mut NativeDecodeControl<'_>,body:&mut NativeSnapshotBodyWallet,depth:usize)->Result<(),ValueError>{let bytes=self.field(control)?;let header=std::mem::size_of::<Vec<u8>>();body.admit_frontier(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:header.checked_add(bytes.len()).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"archive bytes copy extent overflow"))?,maximum_capacity_bytes:bytes.len(),maximum_release_bytes:0,maximum_depth:depth})?;control.scoped_stage(|control|{control.begin_stage(bytes.len())?;control.charge(bytes.len())?;output.try_reserve_exact(bytes.len()).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"archive byte allocation failed"))?;body.record_progress(RetainedCloneProgress{copied_items:1,copied_bytes:header,retained_capacity_bytes:output.capacity(),released_bytes:0})?;for chunk in bytes.chunks(65536){output.extend_from_slice(chunk);body.record_progress(RetainedCloneProgress{copied_bytes:chunk.len(),..Default::default()})?;control.advance(chunk.len())?;}Ok(())})}
 fn reference(&mut self,output:&mut DocumentArchiveArtifactRef,control:&mut NativeDecodeControl<'_>,body:&mut NativeSnapshotBodyWallet)->Result<(),ValueError>{self.text(&mut output.artifact_id,control,body,4)?;self.text(&mut output.artifact_kind,control,body,4)?;self.text(&mut output.standard,control,body,4)?;self.text(&mut output.subset,control,body,4)}
}
/// 📦️ Parses the original archive into one retained partial frame under the caller's physical grant.
pub fn decode_document_archive_bytes_controlled(bytes:&[u8],owner:&mut crate::os_store::NativeSnapshotDecodeOwner<'_, '_>)->Result<DocumentArchivePack,ValueError>{decode(bytes,owner,false)}
/// 📨️ Validates the composed head's empty history before publishing any retained archive fields.
pub fn decode_document_archive_head_controlled(bytes:&[u8],owner:&mut crate::os_store::NativeSnapshotDecodeOwner<'_, '_>)->Result<DocumentArchivePack,ValueError>{decode(bytes,owner,true)}
fn decode(bytes:&[u8],owner:&mut crate::os_store::NativeSnapshotDecodeOwner<'_, '_>,head:bool)->Result<DocumentArchivePack,ValueError>{owner.receive::<DocumentArchivePack,DocumentArchivePack>(|partial,control,body|control.scoped_stage(|control|{
 control.begin_stage(bytes.len())?;if bytes.len()>DOCUMENT_ARCHIVE_MAXIMUM_BYTES||bytes.first()!=Some(&DOCUMENT_ARCHIVE_VERSION){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"unsupported archive version or byte extent"))}control.step()?;
 let header=std::mem::size_of::<Option<DocumentArchivePack>>();body.admit_frontier(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:header,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1})?;*partial=Some(DocumentArchivePack::default());body.record_progress(RetainedCloneProgress{copied_items:1,copied_bytes:header,..Default::default()})?;let output=partial.as_mut().unwrap();let mut reader=Reader{bytes,position:1};reader.bytes(&mut output.parent_pack,control,body,2)?;reader.bytes(&mut output.parent_spr,control,body,2)?;
 if head&&!output.parent_spr.is_empty(){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"composed head archive holds parent history"))}
 let count=usize::try_from(reader.varint(control)?).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"archive member extent exceeds address space"))?;if count>DOCUMENT_ARCHIVE_MAXIMUM_MEMBERS{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"archive member extent exceeds original member ceiling"))}
 body.allocate_vec_into(control,count,&mut output.members,2)?;for _ in 0..count{let member_copy=std::mem::size_of::<OwnedDocumentMemberPackEntry>().checked_add(std::mem::size_of::<u32>()).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"archive member header extent overflow"))?;body.admit_frontier(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:member_copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:3})?;let ordinal=u32::try_from(reader.varint(control)?).map_err(|_|ValueError::literal(ValueRefusalKind::InvalidValue,"archive ordinal exceeds u32"))?;output.members.push(OwnedDocumentMemberPackEntry::default());let member=output.members.last_mut().unwrap();member.ordinal=ordinal;body.record_progress(RetainedCloneProgress{copied_items:1,copied_bytes:member_copy,..Default::default()})?;reader.reference(&mut member.reference,control,body)?;reader.reference(&mut member.owner.parent,control,body)?;reader.text(&mut member.owner.slot,control,body,4)?;reader.text(&mut member.owner.child_id,control,body,4)?;reader.bytes(&mut member.envelope_pack,control,body,4)?;}
 if reader.position!=bytes.len(){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"archive has trailing bytes"))}body.admit_frontier(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:header,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1})?;body.record_progress(RetainedCloneProgress{copied_items:1,copied_bytes:header,..Default::default()})?;Ok(partial.take().unwrap())
}))}
